import fs from "node:fs";
import path from "node:path";
const root = path.resolve(import.meta.dirname, "../src");
const releases = JSON.parse(
  fs.readFileSync(path.join(root, "site/releases.json"), "utf8"),
);
const { version, date, title, summary } = releases[0];
const output =
  "// Generated by scripts/generate-site-content.mjs from published release records.\nexport const upstreamRelease = " +
  JSON.stringify({ version, date, title, summary }, null, 2) +
  " as const;\n";
const file = path.join(root, "shared/upstream-release.generated.ts");
if (process.argv.includes("--check")) {
  if (fs.readFileSync(file, "utf8") !== output)
    throw new Error(
      "Published release summary is stale. Run node scripts/generate-site-content.mjs.",
    );
} else fs.writeFileSync(file, output);
